            sp.lag2_inClose > sp.lag3_inClose &&                         /* consecutive higher closes */
            inOpen > sp.lag1_inClose &&                                  /* 4th opens above prior close */
            inClose < sp.lag3_inOpen ||                                  /* 4th closes below 1st open */
